  window.openStudentMessages=function(){if(!getUser()?.email)return login('login');ensureMessages();db.messages.filter(message=>message.studentEmail===getUser().email&&message.from==='admin').forEach(message=>message.readByStudent=true);save();const thread=db.messages.filter(message=>message.studentEmail===getUser().email).sort((a,b)=>a.date-b.date);window.open('<div class="dialog message-dialog"><div class="dialog-top"><div><p class="eyebrow">DEIN POSTFACH</p><h2>Nachricht an Lehrerin ✉️</h2></div><button class="icon">✕</button></div><div class="message-thread">'+(thread.map(message=>messageBubble(message)).join('')||'<p class="muted">Noch keine Nachrichten. Stelle deiner Lehrerin eine Frage.</p>')+'</div><form class="form message-compose" onsubmit="event.preventDefault();sendStudentMessage()"><label>Neue Nachricht<textarea id="studentMessageText" required placeholder="Deine Frage oder dein Feedback …"></textarea></label><button class="primary">Nachricht senden</button><p id="studentMessageStatus" class="task-feedback"></p></form></div>')};
